"""Installed CLI replay of four externally supplied actual432 public packets."""
import argparse,json,os,subprocess,sys,tempfile
from pathlib import Path
import numpy as np
p=argparse.ArgumentParser();p.add_argument('--runtime',type=Path,required=True);p.add_argument('--source-run',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();r=a.source_run.resolve();runtime=a.runtime.resolve();obs=json.loads((r/'rgb-observations.json').read_text());events=[json.loads(s)for s in(r/'pickup-events.jsonl').read_text().splitlines()];work=Path(tempfile.mkdtemp(prefix='fixed-native-replay-'));rows=[];env=dict(os.environ,FIELD_DEMO_PYTHON=sys.executable,OPENBLAS_NUM_THREADS='1',OMP_NUM_THREADS='1')
